// apps/cli/src/agent/model.ts
/**
 * If the gateway reports the slug as unknown, set a current one with
 * `oxagen config model <slug>` — gateway slugs drift over time.
 */
export const DEFAULT_MODEL = "anthropic/claude-sonnet-4.5";

export function resolveModelId(override?: string): string {
  return (
    override ??
    process.env.OXAGEN_MODEL_SLUG ??
    DEFAULT_MODEL
  );
}

// apps/cli/src/repl/one-shot.ts
import { runTurn, MissingGatewayKeyError } from "../agent/pipeline.js";

/**
 * Run a single non-interactive prompt and exit.
 * @param prompt - The user's prompt text.
 * @param opts   - CLI options forwarded from Commander.
 */
export async function oneShot(prompt: string, opts: OneShotOptions): Promise<void> {
  const result = await runTurn({
    prompt,
    model: resolveModelId(opts.model),
    readonly: opts.readonly,
    verbose: opts.verbose,
  });
}

// apps/cli/src/agent/permissions.ts
/**
 * Oxagen's coding tools (`write_file`, `edit_file`, `bash`) mutate the user's
 * working tree. Any tool NOT in this list is considered read-only and will never
 * trigger an approval prompt in --readonly mode.
 */
export const MUTATING_TOOLS = ["write_file", "edit_file", "bash"] as const;
export type MutatingTool = (typeof MUTATING_TOOLS)[number];

export function isMutatingTool(name: string): name is MutatingTool {
  return (MUTATING_TOOLS as readonly string[]).includes(name);
}

